/bin/sh -lc "node --input-type=module - <<'JS'
import { chromium } from '@playwright/test';
const browser=await chromium.launch();
try {
 const context=await browser.newContext({hasTouch:true,isMobile:true,viewport:{width:360,height:800}});
 const page=await context.newPage();
 await page.goto('file:///work/dist/index.html');
 await page.getByText('Reproduce a game',{exact:true}).click();
 await page.getByLabel('Board code',{exact:true}).fill('np1-16-1');
 await page.getByRole('button',{name:'Load board',exact:true}).click();
 await page.locator('.card').first().tap();
 const scroll=page.locator('.board-scroll');
 await scroll.scrollIntoViewIfNeeded();
 const bounds=await scroll.boundingBox();
 const state=()=>scroll.evaluate(el=>({x:el.scrollLeft,y:el.scrollTop,w:el.clientWidth,h:el.clientHeight,sw:el.scrollWidth,sh:el.scrollHeight,pageY:window.scrollY}));
 console.log('initial',bounds,await state());
 const cdp=await context.newCDPSession(page);
 const gesture={x:bounds.x+bounds.width/2,y:bounds.y+bounds.height/2,gestureSourceType:'touch',speed:1200};
 await cdp.send('Input.synthesizeScrollGesture',{...gesture,xDistance:-1000,yDistance:0});
 console.log('x gesture',await state());
 await page.waitForTimeout(500);
 console.log('after settling x',await state());
 await cdp.send('Input.synthesizeScrollGesture',{...gesture,xDistance:0,yDistance:-1000});
 console.log('y gesture',await state());
 await page.waitForTimeout(500);
 console.log('after settling y',await state());
 await page.screenshot({path:'/work/touch-preview.png',fullPage:true});
} finally {await browser.close();}
JS"

