item.command:
/bin/sh -lc "node --input-type=module - <<'JS'
import { chromium } from '@playwright/test';
const browser=await chromium.launch();
try {
 const context=await browser.newContext({hasTouch:true,isMobile:true,viewport:{width:360,height:800}});
 const page=await context.newPage();
 await page.goto('file:///work/dist/index.html');
 await page.getByLabel('Grid size').selectOption('16');
 const scroll=page.locator('.board-scroll');
 await scroll.scrollIntoViewIfNeeded();
 const box=await scroll.boundingBox();
 const cdp=await context.newCDPSession(page);
 const state=()=>scroll.evaluate(el=>({x:el.scrollLeft,y:el.scrollTop,w:el.clientWidth,h:el.clientHeight,sw:el.scrollWidth,sh:el.scrollHeight}));
 console.log('initial', box, await state());
 await cdp.send('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{x:box.x+box.width-32,y:box.y+100}]});
 for(let i=1;i<=8;i++) {
  await cdp.send('Input.dispatchTouchEvent',{type:'touchMove',touchPoints:[{x:box.x+box.width-32-i*30,y:box.y+100}]});
  await page.waitForTimeout(30);
 }
 await cdp.send('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});
 await page.waitForTimeout(200);
 console.log('after manual', await state());
 await cdp.send('Input.synthesizeScrollGesture',{x:box.x+box.width/2,y:box.y+100,xDistance:-200,yDistance:0,gestureSourceType:'touch',speed:500});
 console.log('after small synthetic', await state());
}finally { await browser.close(); }
JS"

