/bin/sh -lc "node --input-type=module - <<'JS'
import { readdir, readFile, stat } from 'node:fs/promises';
const files=[];
async function walk(path) {
 for(const entry of await readdir(path,{withFileTypes:true})) {
  const name="'`${path}/${entry.name}`;
  if(entry.isDirectory()) await walk(name);
  else if(/'"\\.tsx?"'$/.test(name)) files.push({name,lines:(await readFile(name,'"'utf8')).trimEnd().split('\\n').length});
 }
}
for(const root of ['src','scripts','tests']) await walk(root);
for(const name of ['vite.config.ts','vitest.config.ts','playwright.config.ts']) files.push({name,lines:(await readFile(name,'utf8')).trimEnd().split('\\n').length});
const longest=files.reduce((a,b)=>a.lines>b.lines?a:b);
if(longest.lines>200) throw new Error('Authored TypeScript line limit exceeded.');
console.log(JSON.stringify({distribution:await readdir('dist'),bytes:(await stat('dist/index.html')).size,authoredTypeScriptFiles:files.length,longest},null,2));
JS
